const HIST_MIN_DATE = DAILY_ROOM_MIX.dates[0];
const HIST_MAX_DATE = DAILY_ROOM_MIX.dates[DAILY_ROOM_MIX.dates.length - 1];
// Extend the picker through the live RFP pipeline's horizon — the dashboard
// already carries confirmed and pending group business out to 2027.
const MIX_DISPLAY_MAX_DATE = '2027-12-31';

// Same-day-of-year average transient demand across the 3 historical years,
// used only to fill in a transient estimate beyond HIST_MAX_DATE — there is
// no live transient forecast, only the live group-block pipeline.
function buildTransientClimatology(daily) {
  const sums = {}, counts = {};
  daily.dates.forEach((d, i) => {
    const md = d.slice(5); // 'MM-DD'
    sums[md] = (sums[md] || 0) + daily.transient[i];
    counts[md] = (counts[md] || 0) + 1;
  });
  const avg = {};
  Object.keys(sums).forEach(md => { avg[md] = Math.round(sums[md] / counts[md]); });
  return avg;
}
const TRANSIENT_CLIMATOLOGY = buildTransientClimatology(DAILY_ROOM_MIX);

// dateStr <= HIST_MAX_DATE: exact historical group/transient from the CSV —
// all settled business, no pending-review distinction applies.
// dateStr > HIST_MAX_DATE: group splits into bookedGroupRooms (confirmed) and
// pendingGroupRooms (RFPs still under review, not yet approved), both from the
// live Firestore pipeline; transient is a seasonal estimate, flagged as such.
function mixForDate(dateStr, bookedGroupRooms, pendingGroupRooms) {
  if (dateStr < HIST_MIN_DATE) {
    const idx = 0;
    return { date: HIST_MIN_DATE, group: DAILY_ROOM_MIX.group[idx], bookedGroup: DAILY_ROOM_MIX.group[idx], pendingGroup: 0, transient: DAILY_ROOM_MIX.transient[idx], estimated: false };
  }
  if (dateStr <= HIST_MAX_DATE) {
    const idx = DAILY_ROOM_MIX.dates.indexOf(dateStr);
    if (idx === -1) return { date: dateStr, group: 0, bookedGroup: 0, pendingGroup: 0, transient: 0, estimated: false };
    return { date: dateStr, group: DAILY_ROOM_MIX.group[idx], bookedGroup: DAILY_ROOM_MIX.group[idx], pendingGroup: 0, transient: DAILY_ROOM_MIX.transient[idx], estimated: false };
  }
  const bookedGroup = Math.max(0, Math.min(TOTAL_ROOMS, bookedGroupRooms || 0));
  const pendingGroup = Math.max(0, Math.min(TOTAL_ROOMS - bookedGroup, pendingGroupRooms || 0));
  const group = bookedGroup + pendingGroup;
  const md = dateStr.slice(5);
  const transientEst = TRANSIENT_CLIMATOLOGY[md] ?? Math.round(
    DAILY_ROOM_MIX.transient.reduce((a, b) => a + b, 0) / DAILY_ROOM_MIX.transient.length
  );
  const transient = Math.max(0, Math.min(transientEst, TOTAL_ROOMS - group));
  return { date: dateStr, group, bookedGroup, pendingGroup, transient, estimated: true };
}

function seededShuffle(arr, seed) {
  const a = arr.slice();
  let s = seed;
  for (let i = a.length - 1; i > 0; i--) {
    s = (s * 9301 + 49297) % 233280;
    const j = Math.floor((s / 233280) * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// Fixed seed → the same permutation every render. ROOM_ORDER[rank] = tile
// index filled at that rank; ROOM_RANK[tileIndex] = its rank (the inverse).
